-- Isolated target stores only. FIELD_REFERENCE is supplied by the platform.
CREATE TABLE farm_configuration(id INTEGER PRIMARY KEY CHECK(id=1), cultivation_country TEXT NOT NULL DEFAULT 'GR', revision INTEGER NOT NULL CHECK(revision>0), created_at INTEGER NOT NULL CHECK(created_at>=0), updated_at INTEGER NOT NULL CHECK(updated_at>=created_at));
CREATE TABLE field_identity(field_uuid TEXT NOT NULL PRIMARY KEY, local_field_id INTEGER UNIQUE REFERENCES fields(id) ON DELETE SET NULL, legacy_local_field_key TEXT, deleted_at INTEGER);
CREATE TABLE field_identity_aliases(namespace TEXT NOT NULL, dataset TEXT NOT NULL, alias_uuid TEXT NOT NULL, field_uuid TEXT NOT NULL REFERENCES FIELD_REFERENCE ON DELETE RESTRICT, PRIMARY KEY(namespace,dataset,alias_uuid));
CREATE TABLE cadastral_parcels(parcel_uuid TEXT NOT NULL PRIMARY KEY, country_code TEXT NOT NULL, system_id TEXT NOT NULL, authority_id TEXT NOT NULL, jurisdiction_key TEXT NOT NULL, identifier_key TEXT COLLATE BINARY NOT NULL, identifier_raw TEXT NOT NULL, validator_version TEXT NOT NULL, validation_state TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), created_at INTEGER NOT NULL CHECK(created_at>=0), updated_at INTEGER NOT NULL CHECK(updated_at>=created_at), deleted_at INTEGER, UNIQUE(country_code,system_id,authority_id,jurisdiction_key,identifier_key));
CREATE TABLE cadastral_identifier_spellings(parcel_uuid TEXT NOT NULL REFERENCES cadastral_parcels ON DELETE RESTRICT, raw_value TEXT NOT NULL, origin TEXT NOT NULL, PRIMARY KEY(parcel_uuid,raw_value));
CREATE TABLE cadastral_parcel_aliases(alias_uuid TEXT NOT NULL PRIMARY KEY, parcel_uuid TEXT NOT NULL REFERENCES cadastral_parcels ON DELETE RESTRICT);
CREATE TABLE field_cadastral_links(field_uuid TEXT NOT NULL REFERENCES FIELD_REFERENCE ON DELETE RESTRICT, parcel_uuid TEXT NOT NULL REFERENCES cadastral_parcels ON DELETE RESTRICT, legacy_slot INTEGER NOT NULL CHECK(legacy_slot IN(0,1)), manual_link INTEGER NOT NULL CHECK(manual_link IN(0,1)), revision INTEGER NOT NULL CHECK(revision>0), created_at INTEGER NOT NULL CHECK(created_at>=0), updated_at INTEGER NOT NULL CHECK(updated_at>=created_at), deleted_at INTEGER CHECK(deleted_at IS NULL OR deleted_at BETWEEN created_at AND updated_at), PRIMARY KEY(field_uuid,parcel_uuid), CHECK(deleted_at IS NOT NULL OR legacy_slot=1 OR manual_link=1));
CREATE UNIQUE INDEX cadastral_primary_slot ON field_cadastral_links(field_uuid) WHERE legacy_slot=1 AND deleted_at IS NULL;
CREATE INDEX cadastral_reverse_links ON field_cadastral_links(parcel_uuid,deleted_at);
CREATE TABLE cadastral_snapshots(snapshot_uuid TEXT NOT NULL PRIMARY KEY, parcel_uuid TEXT NOT NULL REFERENCES cadastral_parcels ON DELETE RESTRICT, provider_id TEXT NOT NULL, dataset_id TEXT NOT NULL, dataset_version TEXT NOT NULL, original_geometry_json TEXT NOT NULL, source_payload BLOB NOT NULL, source_crs TEXT NOT NULL, content_hash TEXT NOT NULL, geometry_hash TEXT NOT NULL, provenance_json TEXT NOT NULL, snapshot_date TEXT, source_date TEXT, acquired_at INTEGER NOT NULL CHECK(acquired_at>=0), origin TEXT NOT NULL, official_source_verified INTEGER NOT NULL CHECK(official_source_verified IN(0,1)), UNIQUE(parcel_uuid,content_hash), UNIQUE(parcel_uuid,snapshot_uuid), UNIQUE(parcel_uuid,provider_id,snapshot_uuid));
CREATE TABLE cadastral_parcel_state(parcel_uuid TEXT NOT NULL REFERENCES cadastral_parcels ON DELETE RESTRICT, provider_id TEXT NOT NULL, selected_snapshot_uuid TEXT, selected_revision INTEGER NOT NULL CHECK(selected_revision>0), state TEXT NOT NULL, last_error TEXT, PRIMARY KEY(parcel_uuid,provider_id), FOREIGN KEY(parcel_uuid,provider_id,selected_snapshot_uuid) REFERENCES cadastral_snapshots(parcel_uuid,provider_id,snapshot_uuid));
CREATE TABLE cadastral_lookup_jobs(job_uuid TEXT NOT NULL PRIMARY KEY, parcel_uuid TEXT NOT NULL REFERENCES cadastral_parcels ON DELETE RESTRICT, provider_id TEXT NOT NULL, requested_revision INTEGER NOT NULL, request_uuid TEXT NOT NULL UNIQUE, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt INTEGER, lease_until INTEGER, error TEXT, result_hash TEXT);
CREATE UNIQUE INDEX cadastral_active_job ON cadastral_lookup_jobs(parcel_uuid,provider_id) WHERE status IN('queued','running');
CREATE TABLE cadastral_legacy_bindings(source_table TEXT NOT NULL, source_row_identity TEXT NOT NULL, source_hash TEXT NOT NULL, field_uuid TEXT REFERENCES FIELD_REFERENCE, raw_kaek TEXT NOT NULL, parcel_uuid TEXT REFERENCES cadastral_parcels, snapshot_uuid TEXT REFERENCES cadastral_snapshots, classification TEXT NOT NULL, origin TEXT NOT NULL, source_payload BLOB NOT NULL, PRIMARY KEY(source_table,source_row_identity,source_hash), CHECK(snapshot_uuid IS NULL OR parcel_uuid IS NOT NULL), FOREIGN KEY(parcel_uuid,snapshot_uuid) REFERENCES cadastral_snapshots(parcel_uuid,snapshot_uuid));
CREATE TABLE cadastral_field_overlays(field_uuid TEXT NOT NULL PRIMARY KEY REFERENCES FIELD_REFERENCE, input_fingerprint TEXT NOT NULL, engine TEXT NOT NULL, union_crs TEXT NOT NULL, precision_policy TEXT NOT NULL, geometry_json TEXT, status TEXT NOT NULL, required_count INTEGER NOT NULL CHECK(required_count>=0), usable_count INTEGER NOT NULL CHECK(usable_count BETWEEN 0 AND required_count), diagnostic TEXT NOT NULL, generated_at INTEGER NOT NULL);
CREATE TABLE cadastral_storage_state(id INTEGER PRIMARY KEY CHECK(id=1), schema_version INTEGER NOT NULL, min_writer INTEGER NOT NULL, farm_scope TEXT NOT NULL, activation_id TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN('PREPARED','ACTIVE')), permit INTEGER NOT NULL DEFAULT 0 CHECK(permit IN(0,1)), source_hash TEXT NOT NULL, receipt_hash TEXT NOT NULL);
